/*Table structure for table `void_logs` */

DROP TABLE IF EXISTS `void_logs`;

CREATE TABLE `void_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `order_item_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `product_name` varchar(255) NOT NULL,
  `void_qty` int(11) NOT NULL,
  `refund_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `reason` varchar(255) NOT NULL DEFAULT 'Void สินค้า',
  `voided_by` varchar(150) NOT NULL DEFAULT '',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_void_order` (`order_id`),
  KEY `idx_void_item` (`order_item_id`),
  KEY `idx_void_created` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

